<?php include "db.php"; $u = "admin"; $p = "1"; $stmt = $conn->prepare("SELECT * FROM usuarios WHERE username = ?"); $stmt->bind_param("s", $u); $stmt->execute(); $res = $stmt->get_result()->fetch_assoc(); if ($res) { echo "Usuario encontrado: " . $res["username"] . "<br>Hash en DB: " . $res["password"] . "<br>"; if (password_verify($p, $res["password"])) { echo "<b>La verificación de password es CORRECTA.</b>"; } else { echo "<b>La verificación de password FALLA.</b>"; } } else { echo "Usuario no encontrado."; } ?>